package robot

import "fmt"

// See defs.go for other definitions

// Step 1
// Define N, E, S, W here.

const (
	N Dir = iota
	E
	S
	W
)

func (d Dir) String() string {
	switch d {
	case N:
		return "N"
	case E:
		return "E"
	case S:
		return "S"
	case W:
		return "W"
	}
	return "unknown"
}

func Right() {
	Step1Robot.Dir = (Step1Robot.Dir + 1) % 4
}

func Left() {
	Step1Robot.Dir = (Step1Robot.Dir + 3) % 4
}

func Advance() {
	switch Step1Robot.Dir {
	case N:
		Step1Robot.Y++
	case E:
		Step1Robot.X++
	case S:
		Step1Robot.Y--
	case W:
		Step1Robot.X--
	}
}

// Step 2
// Define Action type here.

// An Action is a single movement expressed in the robot's own frame of
// reference, to be applied by the Room:
//   - a zero Pos is a turn; Dir is the rotation to apply (E turns right,
//     W turns left),
//   - a non-zero Pos is an advance by that displacement, where +Northing
//     is "forward" for the robot,
//   - done marks the end of a robot's command stream.
type Action struct {
	Dir
	Pos
	done bool
}

func StartRobot(command chan Command, action chan Action) {
	for {
		cmd, ok := <-command
		if !ok {
			action <- Action{done: true}
			return
		}
		switch cmd {
		case 'R':
			action <- Action{Dir: E}
		case 'L':
			action <- Action{Dir: W}
		case 'A':
			action <- Action{Pos: Pos{0, 1}}
		}
	}
}

func inRect(r Rect, p Pos) bool {
	return p.Easting >= r.Min.Easting && p.Easting <= r.Max.Easting &&
		p.Northing >= r.Min.Northing && p.Northing <= r.Max.Northing
}

// toWorld rotates a displacement from the robot's frame of reference
// (Easting = right, Northing = forward) into world coordinates, given
// the robot's current direction.
func toWorld(d Dir, p Pos) Pos {
	switch d {
	case N:
		return p
	case E:
		return Pos{p.Northing, -p.Easting}
	case S:
		return Pos{-p.Easting, -p.Northing}
	}
	return Pos{-p.Northing, p.Easting}
}

func Room(extent Rect, robot Step2Robot, action chan Action, report chan Step2Robot) {
	for a := range action {
		if a.done {
			report <- robot
			return
		}
		if a.Pos == Pos{} {
			// Turn: rotate by a.Dir (E = right, W = left).
			robot.Dir = (robot.Dir + a.Dir) % 4
			continue
		}
		// Advance; bumping a wall leaves the robot in place.
		p := toWorld(robot.Dir, a.Pos)
		if np := Pos{robot.Pos.Easting + p.Easting, robot.Pos.Northing + p.Northing}; inRect(extent, np) {
			robot.Pos = np
		}
	}
}

// Step 3
// Define Action3 type here.

// An Action3 is an Action attributed to the named robot.
type Action3 struct {
	Name string
	Action
}

func StartRobot3(name, script string, action chan Action3, log chan string) {
	for _, c := range script {
		switch c {
		case 'R':
			action <- Action3{Name: name, Action: Action{Dir: E}}
		case 'L':
			action <- Action3{Name: name, Action: Action{Dir: W}}
		case 'A':
			action <- Action3{Name: name, Action: Action{Pos: Pos{0, 1}}}
		default:
			log <- fmt.Sprintf("robot %q: bad command %q", name, rune(c))
			action <- Action3{Name: name, Action: Action{done: true}}
			return
		}
	}
	action <- Action3{Name: name, Action: Action{done: true}}
}

func Room3(extent Rect, robots []Step3Robot, action chan Action3, rep chan []Step3Robot, log chan string) {
	// Validate the initial configuration of the room.
	index := make(map[string]int, len(robots))
	occupied := make(map[Pos]bool, len(robots))
	for i, r := range robots {
		if r.Name == "" {
			log <- "a robot has no name"
		}
		if _, dup := index[r.Name]; dup {
			log <- fmt.Sprintf("robot name %q is used more than once", r.Name)
		}
		index[r.Name] = i
		if occupied[r.Pos] {
			log <- fmt.Sprintf("position %v is occupied by more than one robot", r.Pos)
		}
		occupied[r.Pos] = true
		if !inRect(extent, r.Pos) {
			log <- fmt.Sprintf("robot %q starts outside the room", r.Name)
		}
	}

	// Track which robots have acted and which have finished, so the
	// report goes out once every robot that sent an action is done.
	active := make(map[string]bool)
	finished := make(map[string]bool)
	unknown := make(map[string]bool)
	for a := range action {
		active[a.Name] = true
		if i, ok := index[a.Name]; ok {
			apply(&robots[i], i, a.Action, robots, extent, log)
		} else if !unknown[a.Name] {
			unknown[a.Name] = true
			log <- fmt.Sprintf("no robot named %q in the room", a.Name)
		}
		if a.Action.done {
			finished[a.Name] = true
			allDone := true
			for name := range active {
				if !finished[name] {
					allDone = false
					break
				}
			}
			if allDone {
				rep <- robots
				return
			}
		}
	}
}

// apply one action to robot i, logging a message when the robot bumps
// into a wall or another robot.
func apply(r *Step3Robot, i int, a Action, robots []Step3Robot, extent Rect, log chan string) {
	if a.Pos == Pos{} {
		// Turn: rotate by a.Dir (E = right, W = left).
		r.Dir = (r.Dir + a.Dir) % 4
		return
	}
	p := toWorld(r.Dir, a.Pos)
	np := Pos{r.Pos.Easting + p.Easting, r.Pos.Northing + p.Northing}
	if !inRect(extent, np) {
		log <- fmt.Sprintf("robot %q bumps into a wall", r.Name)
		return
	}
	for j, other := range robots {
		if j != i && other.Pos == np {
			log <- fmt.Sprintf("robot %q bumps into robot %q", r.Name, other.Name)
			return
		}
	}
	r.Pos = np
}

